                               `update_by` varchar(64)  NOT NULL DEFAULT '' COMMENT '更新人',
                               `update_time` datetime NOT NULL COMMENT '更新时间',
                               `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
                               `remark` varchar(500)  NULL DEFAULT NULL COMMENT '备注',
                               PRIMARY KEY (`id`) USING BTREE,
                               UNIQUE INDEX `uk_code`(`code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '租户表';

-- ----------------------------
-- Table structure for sys_user
-- ----------------------------
DROP TABLE IF EXISTS `sys_user`;
CREATE TABLE `sys_user`  (
                             `id` bigint NOT NULL COMMENT '主键',
                             `username` varchar(50)  NOT NULL COMMENT '用户名',
                             `nickname` varchar(50)  NOT NULL COMMENT '昵称',
                             `password` varchar(128)  NOT NULL COMMENT '密码(SM3加密)',
                             `salt` varchar(32)  NOT NULL COMMENT '密码盐',
                             `mobile` varchar(30)  NULL DEFAULT NULL COMMENT '手机号',
                             `email` varchar(100)  NULL DEFAULT NULL COMMENT '邮箱',
                             `avatar` varchar(500)  NULL DEFAULT NULL COMMENT '头像URL',
                             `gender` tinyint NULL DEFAULT 0 COMMENT '性别 0=未知 1=男 2=女',
                             `user_type` tinyint NOT NULL DEFAULT 1 COMMENT '用户类型 0=平台超管 1=普通用户',
                             `default_tenant_id` bigint NULL DEFAULT NULL COMMENT '默认租户ID',
                             `dept_id` bigint NULL DEFAULT NULL COMMENT '部门ID',
                             `status` tinyint NOT NULL DEFAULT 1 COMMENT '状态 0=禁用 1=启用',
                             `del_flg` tinyint NOT NULL DEFAULT 0 COMMENT '逻辑删除 0=正常 1=删除',
                             `create_by` varchar(64)  NOT NULL DEFAULT '' COMMENT '创建人',
                             `create_time` datetime NOT NULL COMMENT '创建时间',
                             `update_by` varchar(64)  NOT NULL DEFAULT '' COMMENT '更新人',
                             `update_time` datetime NOT NULL COMMENT '更新时间',
                             `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本号',
                             `remark` varchar(500)  NULL DEFAULT NULL COMMENT '备注',
                             `source` varchar(30)  NULL DEFAULT 'LOCAL' COMMENT '账号来源: LOCAL/GITHUB/WECHAT/WECOM/DINGTALK/FEISHU/OAUTH2/OIDC/SAML2/CAS',
                             PRIMARY KEY (`id`) USING BTREE,
                             UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE,
                             UNIQUE INDEX `uk_mobile`(`mobile` ASC) USING BTREE,
                             UNIQUE INDEX `uk_email`(`email` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户表';

-- ----------------------------
-- Table structure for sys_user_post
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_post`;
CREATE TABLE `sys_user_post`  (
                                  `id` bigint NOT NULL COMMENT '主键',
                                  `user_id` bigint NOT NULL COMMENT '用户ID',
                                  `post_id` bigint NOT NULL COMMENT '岗位ID',
                                  `tenant_id` bigint NOT NULL COMMENT '租户ID',
                                  PRIMARY KEY (`id`) USING BTREE,
                                  UNIQUE INDEX `uk_user_post`(`user_id` ASC, `post_id` ASC, `tenant_id` ASC) USING BTREE,
                                  INDEX `idx_tenant`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户岗位关联表';

-- ----------------------------
-- Table structure for sys_user_role
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_role`;
CREATE TABLE `sys_user_role`  (
                                  `id` bigint NOT NULL COMMENT '主键',
                                  `user_id` bigint NOT NULL COMMENT '用户ID',
                                  `role_id` bigint NOT NULL COMMENT '角色ID',
                                  `tenant_id` bigint NOT NULL COMMENT '租户ID',
                                  PRIMARY KEY (`id`) USING BTREE,
                                  UNIQUE INDEX `uk_user_role`(`user_id` ASC, `role_id` ASC, `tenant_id` ASC) USING BTREE,
                                  INDEX `idx_tenant`(`tenant_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '用户角色关联表';

-- ----------------------------
-- Table structure for sys_user_tenant
-- ----------------------------
DROP TABLE IF EXISTS `sys_user_tenant`;
CREATE TABLE `sys_user_tenant`  (
                                    `id` bigint NOT NULL COMMENT '主键',
                                    `user_id` bigint NOT NULL COMMENT '用户ID',
                                    `tenant_id` bigint NOT NULL COMMENT '租户ID',
                                    `is_default` tinyint NOT NULL DEFAULT 0 COMMENT '是否默认租户',
